[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>DeployCloud Blog — Discover the latest in web development</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg: #FAFAFA;
  --color-surface: #FFFFFF;
  --color-text: #171717;
  --color-text-secondary: #525252;
  --color-text-muted: #737373;
  --color-accent: #0072F5;
  --color-accent-hover: #005BC4;
  --color-accent-light: #E8F1FD;
  --color-border: #E5E5E5;
  --color-border-hover: #D4D4D4;
  --color-pill-bg: #F5F5F5;
  --color-pill-active: #171717;
  --color-pill-active-text: #FFFFFF;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --max-width: 1200px;
  --header-height: 64px;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --transition: 200ms ease;
}

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a { color: inherit; text-decoration: none; }

button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== HEADER ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
  height: var(--header-height);
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.header-left { display: flex; align-items: center; gap: 32px; }

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 800;
  font-size: 18px;
  letter-spacing: -0.03em;
  color: var(--color-text);
}

.logo svg { flex-shrink: 0; }

.logo-divider {
  width: 1px;
  height: 24px;
  background: var(--color-border);
  margin: 0 4px;
}

.logo-blog {
  font-weight: 600;
  font-size: 15px;
  color: var(--color-text-secondary);
}

.nav-links { display: flex; align-items: center; gap: 4px; }

.nav-item {
  position: relative;
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
  display: flex;
  align-items: center;
  gap: 4px;
}

.nav-item:hover { color: var(--color-text); background: var(--color-pill-bg); }

.nav-item svg {
  width: 12px;
  height: 12px;
  transition: transform var(--transition);
}

.nav-item.active svg { transform: rotate(180deg); }

.header-right { display: flex; align-items: center; gap: 8px; }

.btn-ghost {
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}

.btn-ghost:hover { color: var(--color-text); background: var(--color-pill-bg); }

.btn-primary {
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 600;
  color: #FFFFFF;
  background: var(--color-text);
  border-radius: var(--radius-sm);
  transition: background var(--transition);
}

.btn-primary:hover { background: #333333; }

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding: 24px 28px;
  display: none;
  min-width: 560px;
  z-index: 200;
}

.mega-menu.visible {
  display: block;
  animation: menuFadeIn 200ms ease;
}

@keyframes menuFadeIn {
  from { opacity: 0; transform: translateX(-50%) translateY(8px); }
  to { opacity: 1; transform: translateX(-50%) translateY(0); }
}

.mega-menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 24px;
}

.mega-menu-section h4 {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-muted);
  margin-bottom: 12px;
}

.mega-menu-link {
  display: block;
  padding: 6px 0;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text);
  transition: color var(--transition);
}

.mega-menu-link:hover { color: var(--color-accent); }

.mega-menu-link span {
  display: block;
  font-size: 12px;
  font-weight: 400;
  color: var(--color-text-muted);
  margin-top: 1px;
}

.nav-dropdown-wrapper { position: relative; }

/* Mobile menu */
.mobile-toggle {
  display: none;
  padding: 8px;
  color: var(--color-text);
}

.mobile-toggle svg { width: 24px; height: 24px; }

/* ===== HERO / BLOG HEADER ===== */
.blog-hero {
  padding: 56px 0 0;
  text-align: center;
}

.blog-hero h1 {
  font-size: clamp(32px, 5vw, 48px);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.15;
  color: var(--color-text);
  margin-bottom: 12px;
}

.blog-hero p {
  font-size: 17px;
  color: var(--color-text-secondary);
  max-width: 520px;
  margin: 0 auto;
  line-height: 1.6;
}

/* ===== CATEGORY FILTERS ===== */
.filters-section {
  padding: 32px 0 8px;
  position: sticky;
  top: var(--header-height);
  z-index: 50;
  background: var(--color-bg);
}

.filters-inner {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.filters-pills {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  flex: 1;
}

.pill {
  padding: 7px 16px;
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-secondary);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  transition: all var(--transition);
  white-space: nowrap;
}

.pill:hover {
  border-color: var(--color-border-hover);
  color: var(--color-text);
}

.pill.active {
  background: var(--color-pill-active);
  color: var(--color-pill-active-text);
  border-color: var(--color-pill-active);
}

.search-box {
  position: relative;
  min-width: 220px;
}

.search-box svg {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  color: var(--color-text-muted);
  pointer-events: none;
}

.search-input {
  width: 100%;
  padding: 8px 12px 8px 36px;
  font-size: 14px;
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  outline: none;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.search-input::placeholder { color: var(--color-text-muted); }

.search-input:focus {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(0,114,245,0.1);
}

/* ===== FEATURED ARTICLES ===== */
.featured-section { padding: 40px 0; }

.featured-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.featured-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), box-shadow var(--transition);
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.featured-card:hover {
  border-color: var(--color-border-hover);
  box-shadow: var(--shadow-md);
}

.featured-card.primary {
  grid-row: 1 / 3;
  background: linear-gradient(135deg, #171717 0%, #262626 100%);
  border-color: #333;
  color: #FFFFFF;
}

.featured-card.primary:hover { border-color: #555; box-shadow: var(--shadow-lg); }

.featured-card.primary .featured-meta { color: rgba(255,255,255,0.6); }
.featured-card.primary .featured-excerpt { color: rgba(255,255,255,0.7); }
.featured-card.primary .featured-author-name { color: #FFFFFF; }
.featured-card.primary .featured-tag { background: rgba(255,255,255,0.15); color: rgba(255,255,255,0.9); border-color: rgba(255,255,255,0.2); }

.featured-tag {
  display: inline-block;
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: var(--radius-full);
  background: var(--color-accent-light);
  color: var(--color-accent);
  border: 1px solid transparent;
  margin-bottom: 16px;
}

.featured-title {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.featured-card.primary .featured-title { font-size: 28px; }

.featured-excerpt {
  font-size: 14px;
  line-height: 1.65;
  color: var(--color-text-secondary);
  margin-bottom: 24px;
  flex: 1;
  display: -webkit-box;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.featured-card.primary .featured-excerpt {
  -webkit-line-clamp: 6;
}

.featured-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 13px;
  color: var(--color-text-muted);
  margin-top: auto;
}

.featured-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--color-accent), #6366F1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 600;
  color: #FFFFFF;
  flex-shrink: 0;
}

.featured-author-name { font-weight: 600; color: var(--color-text); }

/* Stats strip inside primary card */
.stats-strip {
  display: flex;
  gap: 20px;
  margin-top: 20px;
  padding-top: 20px;
  border-top: 1px solid rgba(255,255,255,0.15);
  flex-wrap: wrap;
}

.stat-item { flex: 1; min-width: 100px; }

.stat-value {
  font-size: 24px;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: #FFFFFF;
  line-height: 1.2;
}

.stat-label {
  font-size: 12px;
  color: rgba(255,255,255,0.55);
  margin-top: 2px;
  line-height: 1.4;
}

/* ===== LATEST NEWS ===== */
.latest-section { padding: 8px 0 56px; }

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}

.section-title {
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.posts-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.post-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 24px;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
  cursor: pointer;
}

.post-card:hover {
  border-color: var(--color-border-hover);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.post-tag {
  display: inline-block;
  padding: 3px 8px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: var(--radius-sm);
  color: var(--color-accent);
  background: var(--color-accent-light);
  margin-bottom: 12px;
  align-self: flex-start;
}

.post-tag.engineering { color: #7C3AED; background: #F3EEFF; }
.post-tag.customers { color: #059669; background: #ECFDF5; }
.post-tag.community { color: #D97706; background: #FFFBEB; }
.post-tag.company-news { color: #DC2626; background: #FEF2F2; }
.post-tag.security { color: #0891B2; background: #ECFEFF; }
.post-tag.changelog { color: #7C3AED; background: #F3EEFF; }
.post-tag.press { color: #64748B; background: #F1F5F9; }
.post-tag.v0 { color: #171717; background: #F5F5F5; }

.post-date {
  font-size: 12px;
  color: var(--color-text-muted);
  margin-bottom: 8px;
}

.post-title {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: -0.01em;
  margin-bottom: 8px;
  color: var(--color-text);
}

.post-excerpt {
  font-size: 14px;
  line-height: 1.6;
  color: var(--color-text-secondary);
  flex: 1;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-bottom: 16px;
}

.post-author {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: auto;
  padding-top: 16px;
  border-top: 1px solid var(--color-border);
}

.post-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--color-accent), #6366F1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 600;
  color: #FFFFFF;
  flex-shrink: 0;
}

.post-author-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text);
}

/* No results */
.no-results {
  text-align: center;
  padding: 80px 24px;
  color: var(--color-text-muted);
  font-size: 15px;
  display: none;
  grid-column: 1 / -1;
}

.no-results.visible { display: block; }

.no-results svg {
  width: 48px;
  height: 48px;
  color: var(--color-border);
  margin-bottom: 16px;
}

.no-results p { margin-top: 8px; font-size: 14px; }

/* Show more */
.show-more-wrapper {
  text-align: center;
  margin-top: 40px;
}

.btn-show-more {
  padding: 12px 32px;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  transition: all var(--transition);
}

.btn-show-more:hover {
  border-color: var(--color-text);
  box-shadow: var(--shadow-sm);
}

/* ===== CTA BANNER ===== */
.cta-section { padding: 40px 0 64px; }

.cta-banner {
  background: linear-gradient(135deg, #171717 0%, #1E293B 100%);
  border-radius: var(--radius-lg);
  padding: 56px 48px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 40px;
  align-items: center;
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 400px;
  height: 400px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(0,114,245,0.15) 0%, transparent 70%);
  pointer-events: none;
}

.cta-content h2 {
  font-size: clamp(24px, 3vw, 32px);
  font-weight: 800;
  color: #FFFFFF;
  line-height: 1.25;
  letter-spacing: -0.03em;
  margin-bottom: 12px;
}

.cta-content p {
  font-size: 15px;
  color: rgba(255,255,255,0.65);
  line-height: 1.6;
  max-width: 480px;
}

.cta-content p strong { color: rgba(255,255,255,0.9); font-weight: 600; }

.cta-buttons { display: flex; gap: 12px; flex-shrink: 0; }

.btn-cta-primary {
  padding: 12px 28px;
  font-size: 14px;
  font-weight: 600;
  color: #171717;
  background: #FFFFFF;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
}

.btn-cta-primary:hover { background: #F0F0F0; transform: translateY(-1px); }

.btn-cta-secondary {
  padding: 12px 28px;
  font-size: 14px;
  font-weight: 600;
  color: #FFFFFF;
  background: transparent;
  border: 1px solid rgba(255,255,255,0.3);
  border-radius: var(--radius-sm);
  transition: all var(--transition);
}

.btn-cta-secondary:hover { border-color: rgba(255,255,255,0.6); background: rgba(255,255,255,0.08); }

/* Enterprise sub-block */
.enterprise-block {
  margin-top: 20px;
  padding: 24px 32px;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.enterprise-block p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

.btn-enterprise {
  padding: 10px 24px;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-accent);
  background: var(--color-accent-light);
  border-radius: var(--radius-sm);
  white-space: nowrap;
  transition: all var(--transition);
}

.btn-enterprise:hover { background: #D4E6FB; }

/* ===== FOOTER ===== */
.footer {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding: 56px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
  margin-bottom: 48px;
}

.footer-column h5 {
  font-size: 13px;
  font-weight: 700;
  color: var(--color-text);
  margin-bottom: 16px;
  letter-spacing: -0.01em;
}

.footer-column a {
  display: block;
  font-size: 13px;
  color: var(--color-text-muted);
  padding: 4px 0;
  transition: color var(--transition);
}

.footer-column a:hover { color: var(--color-text); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 24px;
  border-top: 1px solid var(--color-border);
}

.footer-bottom-left {
  display: flex;
  align-items: center;
  gap: 20px;
}

.footer-logo {
  font-weight: 800;
  font-size: 16px;
  color: var(--color-text);
  display: flex;
  align-items: center;
  gap: 6px;
}

.footer-status {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--color-text-muted);
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #22C55E;
}

.footer-legal {
  display: flex;
  gap: 16px;
  font-size: 12px;
  color: var(--color-text-muted);
}

.footer-legal a:hover { color: var(--color-text); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 900px) {
  .featured-grid { grid-template-columns: 1fr; }
  .featured-card.primary { grid-row: auto; }
  .posts-grid { grid-template-columns: repeat(2, 1fr); }
  .cta-banner { grid-template-columns: 1fr; text-align: center; }
  .cta-buttons { justify-content: center; }
  .cta-content p { margin: 0 auto; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .mobile-toggle { display: flex; }
  .header-right .btn-ghost.ask-ai,
  .header-right .btn-ghost.login { display: none; }
  .filters-inner { flex-direction: column; align-items: stretch; }
  .search-box { min-width: auto; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .enterprise-block { flex-direction: column; text-align: center; }
}

@media (max-width: 640px) {
  .posts-grid { grid-template-columns: 1fr; }
  .featured-card { padding: 24px; }
  .featured-card.primary .featured-title { font-size: 22px; }
  .stats-strip { flex-direction: column; gap: 12px; }
  .cta-banner { padding: 40px 24px; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 24px; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
  .footer-bottom-left { flex-direction: column; }
}

/* Focus / A11y */
:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* Overlay for closing menus */
.menu-overlay {
  position: fixed;
  inset: 0;
  z-index: 99;
  display: none;
}

